with open("/home/runner/.nuget/packages/xunit.v3.extensibility.core/1.1.0/lib/netstandard2.0/xunit.v3.core.dll", "rb") as f:
    data = f.read()
# Search for any type containing "Fact" in the type definitions
# Let's look for patterns with namespace prefix
for pattern in [rb"Xunit\.v3\.[A-Za-z]+", rb"Xunit\.[A-Z][A-Za-z]+"]:
    matches = set()
    for m in re.finditer(pattern, data):
        try:
            s = m.group(0).decode("utf-8")
            if 'Fact' in s or 'Theory' in s or 'Attribute' in s:
                matches.add(s)
        except:
            pass
    for m in sorted(matches):
        print(m)
EOF
